python
def cancelingStampsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a:
        if out and out[-1]==x: out.pop()
        else: out.append(x)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int cancelingStampsFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){if(!out.isEmpty()&&out.get(out.size()-1)==x)out.remove(out.size()-1);else out.add(x);}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
